\subsection{Global Clustering Analysis}

\begin{figure}[h!]
    \centering
    \includegraphics{../figures/metabolic_umap.pdf}
    \caption{UMAP embedding of 58,843 cells clustered using Leiden algorithm on 1,984 metabolic genes. Cluster sizes range from 1,002 to 8,985 cells across 15 clusters.}
    \label{fig:metabolic_umap}
\end{figure}

Figure~\ref{fig:metabolic_umap} shows the UMAP embedding of cells using the metabolic gene set. The clustering identified 15 distinct groups with varying sizes, ranging from 1,002 to 8,985 cells.

\subsection{Clustering Diagnostics}

\begin{figure}[h!]
    \centering
    \includegraphics{../figures/clustering_diagnostics.pdf}
    \caption{Clustering diagnostics including silhouette scores, Calinski-Harabasz index, Davies-Bouldin index, and pairwise ARI/NMI metrics across seeds and resolutions.}
    \label{fig:clustering_diagnostics}
\end{figure}

Figure~\ref{fig:clustering_diagnostics} shows the clustering diagnostics. The selected resolution (0.4) maximized median silhouette among candidates passing the mean pairwise ARI stability filter; mean pairwise ARI was the tie-breaker.

\subsection{Clustering Metrics}

\begin{table}[h!]

